const email = $('Form').first().json['Add Candidate\'s Email Address:'];
const jd = $('On form submission').first().json['Enter Detailed Job Description:'];
const resumeText = $input.first().json.text;

return {
  email: email,
  jd: jd,
  resume: resumeText,
  chatInput: `SYSTEM CONTEXT (not a candidate answer):
Job Description: ${jd}
Resume: ${resumeText}
---
You now have all context. Begin Phase 1 silently, then ask your first assessment question.
IMPORTANT: When you have assessed ALL required skills and are delivering the final report, you MUST begin your response with the phrase "Validated Proficiencies" so the system knows the assessment is complete.`
};

const answer = $json["Your Answer"] || "";
const email = $json["email"] || "";

return {
  email: email,
  chatInput: answer
};

const rawOutput = $json.output || "";

const sanitized = rawOutput
  // Remove markdown bold
  .replace(/\*\*(.*?)\*\*/g, '$1')

  // Remove markdown headers
  .replace(/^#{1,3} /gm, '')

  // Clean bullet points to plain dash
  .replace(/^- /gm, '• ')

  // Collapse 3+ newlines to 2
  .replace(/\n{3,}/g, '\n\n')

  // Remove any HTML tags if AI accidentally outputs them
  .replace(/<[^>]*>/g, '')

  // Remove problematic quote characters that break form JSON
  .replace(/"/g, "'")

  .trim();

return {
  output: sanitized,
  email: $('Form').first().json['Add Candidate\'s Email Address:']
};
